import{B,C,read,path,ray}from'../ten-utils.js';import{mirrorImage,lensImage,refractedAngle,fmt10}from'../ten-math.js';
export default({g,p,extra})=>{let m=extra.mode??0,d=p[0];if(m===2){let r=refractedAngle(d),i=d*Math.PI/180,rr=r*Math.PI/180;g.line([-1.5,0,0],[1.5,0,0],C.blue,3);g.line([0,-1,0],[0,1,0],C.dark);ray(g,[-Math.sin(i),-Math.cos(i),0],[0,0,0]);ray(g,[0,0,0],[Math.sin(rr),Math.cos(rr),0]);g.text(-1,-.8,0,B('Air n = 1','वायु n = 1'));g.text(-1,.8,0,B('Glass n = 1.5','काँच n = 1.5'));return[read('Incidence angle','आपतन कोण',d,'°'),read('Refraction angle','अपवर्तन कोण',fmt10(r),'°'),read('Law','नियम','n1 sin i = n2 sin r')]}
let a=m===0?mirrorImage(d):lensImage(d),scale=.025,ox=-d*scale,h=.3;g.line([-1.6,0,0],[1.6,0,0],C.dark);g.arrow([ox,0,0],[ox,-h,0],C.green);g.text(ox,.2,0,B('Object','वस्तु'));if(m===0){path(g,Array.from({length:25},(_,i)=>{let y=(i-12)*.065;return[-y*y*.12,y,0]}),C.blue,4)}else{path(g,Array.from({length:25},(_,i)=>{let y=(i-12)*.065;return[.08*(1-y*y),y,0]}),C.blue,3);path(g,Array.from({length:25},(_,i)=>{let y=(i-12)*.065;return[-.08*(1-y*y),y,0]}),C.blue,3)}
for(let x of(m===0?[-.375]:[-.375,.375])){g.sphere(x,0,0,.025,C.gold);g.text(x,.2,0,'F')}
ray(g,[ox,-h,0],[0,-h,0]);ray(g,[ox,-h,0],[0,0,0]);let slope=h/(d*scale),length=Math.min(1.3,.85/slope);ray(g,[0,0,0],[m===0?-length:length,length*slope,0]);let target=m===0?[-.375,0,0]:[.375,0,0];ray(g,[0,-h,0],target);if(!a.infinity){let ix=a.v*scale,iy=-a.m*h;if(Math.abs(ix)<1.5&&Math.abs(iy)<1){g.arrow([ix,0,0],[ix,iy,0],C.pink);g.text(ix,iy-.15,0,B('Image','प्रतिबिंब'));if((m===0&&a.v>0)||(m===1&&a.v<0)){for(let j=0;j<12;j+=2){let f=j/12,q=(j+1)/12;g.line([ix*f,-h+(iy+h)*f,0],[ix*q,-h+(iy+h)*q,0],C.pink);g.line([ix*f,iy*f,0],[ix*q,iy*q,0],C.pink)}}else g.line([0,-h,0],[ix,iy,0],C.pink)}else g.text(.8,.8,0,B('Image beyond display','प्रतिबिंब दृश्य सीमा से बाहर'))}return[read('Signed object distance u','चिह्न सहित वस्तु दूरी u',a.u,'cm'),read('Focal length f','फोकस दूरी f',a.f,'cm'),read('Image distance v','प्रतिबिंब दूरी v',a.infinity?B('At infinity','अनंत पर'):fmt10(a.v),'cm'),read('Magnification','आवर्धन',a.infinity?'—':fmt10(a.m))]};
